import{Engine,esc}from'./base.js';
export function drawPot(canvas,step=9,level='Good',palette=[]){let C=palette.length?palette.map(p=>p.color):['#F6EBD6','#D8A275','#B96C43','#70432F','#34302C'];let g=canvas.getContext('2d'),sx=canvas.width/600,sy=canvas.height/400;g.setTransform(sx,0,0,sy,0,0);g.clearRect(0,0,600,400);g.fillStyle=C[0];g.fillRect(0,0,600,400);if(step>=8){let b=g.createLinearGradient(0,0,0,400);b.addColorStop(0,'#ebe9dc');b.addColorStop(1,'#fffdf5');g.fillStyle=b;g.fillRect(0,0,600,400);g.strokeStyle='#cbc7b8';g.beginPath();g.moveTo(40,335);g.lineTo(560,335);g.stroke()}if(step>=7){g.save();g.translate(330,339);g.scale(1,.21);let sh=g.createRadialGradient(0,0,10,0,0,155);sh.addColorStop(0,'#35372e70');sh.addColorStop(1,'#35372e00');g.fillStyle=sh;g.beginPath();g.arc(0,0,155,0,Math.PI*2);g.fill();g.restore()}let pot=new Path2D('M210 100 C214 123 213 140 198 150 C135 178 139 270 180 310 C210 346 310 346 340 310 C384 265 380 183 322 150 C307 140 307 121 310 100 Z');g.lineWidth=step>=9?1.7:1;g.strokeStyle=step>=2?C[4]:'#b4b0a1';if(step>=4){let fill=g.createLinearGradient(155,0,380,0);fill.addColorStop(0,C[1]);fill.addColorStop(.28,C[0]);fill.addColorStop(.58,step>=5?C[2]:C[1]);fill.addColorStop(1,step>=6?C[3]:C[1]);g.fillStyle=fill;g.fill(pot)}g.stroke(pot);if(step<=1){g.setLineDash([5,5]);g.strokeStyle='#b3b8aa';g.beginPath();g.ellipse(260,235,112,100,0,0,Math.PI*2);g.stroke();if(step===1){g.beginPath();g.moveTo(260,55);g.lineTo(260,355);g.moveTo(135,150);g.lineTo(385,150);g.stroke()}g.setLineDash([])}if(step>=2){g.fillStyle=step>=5?'#6e604a':'#dcd4bd';g.beginPath();g.ellipse(260,100,50,10,0,0,Math.PI*2);g.fill();g.stroke();g.beginPath();g.ellipse(260,105,50,10,0,0,Math.PI);g.stroke()}if(step>=3){g.strokeStyle='#9a906b';g.beginPath();g.moveTo(85,45);g.lineTo(160,103);g.lineTo(146,101);g.moveTo(160,103);g.lineTo(156,90);g.stroke();g.fillStyle='#6e6b5f';g.font='13px Inter, sans-serif';g.fillText('Light / प्रकाश',45,35)}if(step>=6&&level!=='Beginner'){g.save();g.clip(pot);g.strokeStyle=C[4]+'55';g.lineWidth=.6;for(let i=0;i<23;i++){g.beginPath();g.moveTo(305+i*3,140);g.lineTo(285+i*3,335);g.stroke()}g.restore()}if(step>=7){g.save();g.clip(pot);let hi=g.createRadialGradient(215,210,0,215,210,45);hi.addColorStop(0,'#fffdf4b0');hi.addColorStop(1,'#fffdf400');g.fillStyle=hi;g.fillRect(170,155,95,120);g.restore()}if(level==='Beginner'){g.strokeStyle='#6b6458';g.lineWidth=3;g.stroke(pot)}if(level==='Intermediate'){g.strokeStyle='#8c8068';g.lineWidth=1.2;g.stroke(pot)}if(step>=9){g.fillStyle='#84745b';g.font='12px Inter, sans-serif';g.fillText('Light → mid-tone → shadow | प्रकाश → मध्यम टोन → छाया',90,380)}}
export {drawArtwork}from './artwork.js';
import{drawArtwork}from './artwork.js';
export default class Step extends Engine{
 constructor(h,c){super(h,c);this.step=0;this.highlight=null;const ch=c.chapter;this.last=ch.artStepTips.length-1;this.unlocked=0;this.technical=ch.artTopic>=6&&ch.artTopic<=9;this.spot=ch.spotStep||{question:{en:'Which step adds the highlight?',hi:'किस चरण में चमक जोड़ी जाती है?'},correct:7,reason:{en:'Step 8 adds the highlight and cast shadow.',hi:'चरण 8 में चमक और पड़ी हुई छाया जुड़ती है।'}};h.innerHTML=`<canvas class="artCanvas" width="1200" height="800" role="img" tabindex="0" aria-label="${c.dual(ch.title.en+' guided drawing',ch.title.hi+' का निर्देशित चित्र')}"></canvas><div class="engineTools"><button data-step="prev">${c.label('← Previous','← पिछला')}</button><button data-step="next">${c.label('Next step →','अगला चरण →')}</button><label>${c.label('Step','चरण')}<input type="range" min="0" max="${this.last}" step="1" value="0"></label></div><article class="stepTip" aria-live="polite"></article><div class="artPalette">${ch.palette.map((p,i)=>`<button data-palette="${i}" style="--swatch:${p.color}" aria-label="${c.dual(p.name.en,p.name.hi)}"><i></i>${c.label(p.name.en,p.name.hi)}</button>`).join('')}</div><p class="paletteText" role="status"></p><label>${c.label(this.spot.question.en,this.spot.question.hi)}<select class="spotStep"><option value="">${c.dual('Choose a step','चरण चुनें')}</option>${ch.artStepTips.map((s,i)=>`<option value="${i}">${i+1}. ${c.dual(s.title.en,s.title.hi)}</option>`).join('')}</select></label><p class="spotFeedback" role="status"></p>`;this.canvas=h.querySelector('canvas');if(c.lowPower){this.canvas.width=600;this.canvas.height=400}
 this.on(h,'click',e=>{let b=e.target.closest('[data-step]'),p=e.target.closest('[data-palette]');if(b)this.move(b.dataset.step==='next'?1:-1);if(p){let i=+p.dataset.palette;this.highlight=ch.artTopic?null:i;if(!this.technical)this.step=this.last;this.metrics.palette=true;this.metrics.selectedColour=true;h.querySelector('.paletteText').textContent=c.text(ch.palette[i].usage||(ch.artTopic?{en:ch.palette[i].name.en+': compare this swatch with the drawing; shading mixes light and dark tones.',hi:ch.palette[i].name.hi+': इस रंग की चित्र से तुलना करें; छायांकन में हल्के और गहरे तान मिलते हैं।'}:{en:ch.palette[i].name.en+': the dashed gold ring marks an example area in the finished drawing.',hi:ch.palette[i].name.hi+': सुनहरा बिंदीदार घेरा पूरे चित्र में इस रंग का 1 उदाहरण भाग दिखाता है।'}));this.render()}});
 this.on(h.querySelector('input'),'input',e=>{this.step=this.technical?Math.min(this.unlocked,+e.target.value):+e.target.value;this.render()});this.on(this.canvas,'keydown',e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();this.move(e.key==='ArrowRight'?1:-1)}});this.on(h.querySelector('.spotStep'),'change',e=>{let ok=e.target.value!==''&&+e.target.value===this.spot.correct;this.metrics.spot=ok;this.metrics.highlight=ok;h.querySelector('.spotFeedback').textContent=c.dual(ok?'Correct. ':'Look again. ',ok?'सही। ':'फिर देखें। ')+c.text(this.spot.reason);this.emit(h.querySelector('.spotFeedback').textContent)});if(ch.artTopic){let note=document.createElement('p');note.className='artModelNote';note.textContent=c.dual('Original teaching drawing. Screen sizes are symbolic; use a ruler for the written measurements. '+(this.technical?'Use Next to complete each construction stage.':'The shading is a simplified tonal model.'),'मौलिक शिक्षण चित्र। स्क्रीन का आकार सांकेतिक है; लिखे माप के लिए पटरी उपयोग करें। '+(this.technical?'Next से रचना का प्रत्येक चरण पूरा करें।':'छायांकन तान का सरल मॉडल है।'));h.append(note);let b=document.createElement('button');b.type='button';b.textContent=c.dual('Download drawing PNG','चित्र PNG डाउनलोड करें');h.append(b);this.on(b,'click',()=>{let a=document.createElement('a');a.download=ch.id+'-step-'+(this.step+1)+'.png';a.href=this.canvas.toDataURL('image/png');a.click()})}this.render()}
 move(d){this.step=Math.max(0,Math.min(this.last,this.step+d));this.unlocked=Math.max(this.unlocked,this.step);this.render()}render(){drawArtwork(this.canvas,this.ctx.chapter.artTopic?{...this.ctx.chapter,hideLabels:!this.labels}:this.ctx.chapter,this.step,'Good');if(this.highlight!==null){const regions={pot:[[50,300,25,20],[195,210,24,60],[265,235,25,70],[335,245,24,60],[260,100,54,14]],fruit:[[50,70,25,20],[220,230,35,45],[395,225,30,45],[250,123,23,14],[285,280,20,20]],jug:[[50,70,25,20],[265,225,30,50],[200,225,15,45],[310,260,18,35],[260,98,35,8]],drapery:[[50,70,25,20],[165,150,15,35],[270,215,15,40],[320,240,12,40],[350,313,45,8]],border:[[300,190,30,20],[140,83,15,11],[140,83,5,5],[300,100,35,5],[80,200,8,25]],poster:[[180,120,15,15],[310,215,25,30],[274,225,12,20],[300,310,60,12],[300,80,70,15]],lettering:[[100,70,20,20],[290,195,35,35],[290,170,30,20],[300,275,45,5],[250,220,30,25]]};let z=this.ctx.chapter.artTopic?[[45,45,20,20],[300,100,18,18],[300,205,18,18],[430,280,18,18],[300,330,18,18]][this.highlight]:(regions[this.ctx.chapter.drawingKind||'pot']||regions.pot)[this.highlight],g=this.canvas.getContext('2d');g.save();g.strokeStyle='#c18a1a';g.lineWidth=3;g.setLineDash([6,4]);g.beginPath();g.ellipse(...z,0,0,Math.PI*2);g.stroke();g.restore()}this.host.querySelector('input').value=this.step;if(this.technical)this.host.querySelector('input').max=this.unlocked;let s=this.ctx.chapter.artStepTips[this.step];this.host.querySelector('.stepTip').innerHTML=this.ctx.H(s.title,3)+`<p>${esc(this.ctx.text(s.tip))}</p>`;this.host.querySelector('[data-step="prev"]').disabled=this.step===0;this.host.querySelector('[data-step="next"]').disabled=this.step===this.last;this.metrics.step=this.step;this.emit(`${this.ctx.dual('Step','चरण')} ${this.step+1} / ${this.last+1}: ${this.ctx.text(s.tip)}`)}run(){if(this.step===this.last){this.playing=false;this.ctx.playing(false);return}this.schedule(()=>{this.move(1);this.run()},1800)}resetView(){this.step=0;this.render()}setLabels(v){this.labels=v;this.render();this.host.querySelector('.stepTip').hidden=!v}
}
